options.queryReplacement:
={{ (() => {
  // `identity.guest_id` is Flask's session id, which is a UUID for a
  // browser but NOT for every caller -- the smoke suite sends
  // 'guest-smoke-001'. Casting that to ::uuid fails the whole INSERT,
  // and the feedback intent then reports UPSTREAM_ERROR for what is
  // really a well-formed request. Non-UUID identities are stored in
  // the context JSON instead of the typed column, so the event is
  // still recorded and still attributable.
  const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  const t = $('When Executed by Another Workflow').item.json;
  const rawGuest = t.envelope?.identity?.guest_id || null;
  const guestUuid = rawGuest && uuidRe.test(rawGuest) ? rawGuest : null;
  const userUuid = t.user_id && uuidRe.test(t.user_id) ? t.user_id : null;
  const fb = t.envelope?.body?.feedback || {};
  return [
    (fb.action || 'like'),
    userUuid,
    guestUuid,
    JSON.stringify(Object.assign({}, fb, {
      request_id: t.request_id,
      idempotency_key: t.idempotency_key,
      guest_id: rawGuest,
      user_id: t.user_id || null,
      discovery_mode: (t.envelope?.body?.recommendation_context?.discovery_mode || null),
    })),
    (t.idempotency_key || ''),
  ];
})() }}
